{"sql": "-- Let me check: for noballs, do they have corresponding batsman_scored entries?
SELECT COUNT(*) FROM extra_runs e
WHERE e.extra_type = 'noballs' AND EXISTS (
    SELECT 1 FROM batsman_scored bs 
    WHERE e.match_id = bs.match_id AND e.over_id = bs.over_id AND e.ball_id = bs.ball_id AND e.innings_no = bs.innings_no
)"}

